/**
 * @name Command injection via subprocess
 * @description User-controlled data flowing to subprocess execution can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection-dotenv
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Sources: file reads, user input, environment variables
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      source = call.getAMethodCall("read")
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      source = call.getAMethodCall("read_text")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "file content"

/**
 * @name Path traversal in file operations
 * @description User-controlled file paths without validation can lead to unauthorized file access
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-dotenv
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters that could be user-controlled
    exists(DataFlow::ParameterNode param |
      source = param and
      param.getParameter().getName() in ["dotenv_path", "path", "filename", "stream_or_path"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled path"

/**
 * @name Shell injection via subprocess with shell=True
 * @description Using subprocess with shell=True and user-controlled input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/shell-injection-dotenv
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ShellInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // File content or user input
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      source = call.getAMethodCall("read")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // subprocess calls with shell=True
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["run", "call", "Popen", "check_call", "check_output"]).getACall() and
      call.getArgByName("shell").asExpr().(BooleanLiteral).booleanValue() = true and
      sink = call.getArg(0)
    )
  }
}

module ShellInjectionFlow = TaintTracking::Global<ShellInjectionConfig>;
import ShellInjectionFlow::PathGraph

from ShellInjectionFlow::PathNode source, ShellInjectionFlow::PathNode sink
where ShellInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Shell injection from $@.", source.getNode(), "file content"
